import json
import re
import datetime


def g(k, d=''):
    x = vars.get(k)
    if x is None:
        return d
    if isinstance(x, str):
        return x
    return str(x)


def gi(k, d=0):
    try:
        return int(float(g(k, str(d)) or d))
    except Exception:
        return d


def fnum(x):
    try:
        return float(x)
    except Exception:
        return 0.0


def jload(k, d):
    try:
        v = json.loads(g(k))
        return v
    except Exception:
        return d


# ---------------------------------------------------------------- speech helpers
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
MONTHS = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos',
          'Eylül', 'Ekim', 'Kasım', 'Aralık']
ORD = ['', 'birinci', 'ikinci', 'üçüncü', 'dördüncü']
CUR = [('TL', 'debtTL', 'Türk Lirası', 'kuruş'), ('USD', 'debtUSD', 'Dolar', 'sent'),
       ('EUR', 'debtEUR', 'Euro', 'sent'), ('GBP', 'debtGBP', 'İngiliz Sterlini', 'peni')]


def w3(n):
    parts = []
    h = n // 100
    r = n % 100
    if h:
        parts.append('yüz' if h == 1 else ONES[h] + ' yüz')
    if r // 10:
        parts.append(TENS[r // 10])
    if r % 10:
        parts.append(ONES[r % 10])
    return ' '.join(parts)


def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    out = []
    for size, name in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        q = n // size
        if q:
            if size == 1000 and q == 1:
                out.append('bin')
            else:
                out.append(w3(q) + ' ' + name)
            n = n % size
    if n:
        out.append(w3(n))
    return ' '.join(out)


def money(x, cur):
    unit = 'Türk Lirası'
    sub = 'kuruş'
    for c in CUR:
        if c[0] == cur:
            unit = c[2]
            sub = c[3]
    cents = int(round(abs(fnum(x)) * 100))
    whole = cents // 100
    frac = cents % 100
    s = words(whole) + ' ' + unit
    if frac:
        s = s + ' ' + words(frac) + ' ' + sub
    return s


def suffix_for(spoken):
    w = spoken.strip().split(' ')[-1].lower() if spoken.strip() else 'a'
    vowel = 'a'
    for ch in reversed(w):
        if ch in 'aıoueiöü':
            vowel = ch
            break
    i = dict(a='ı', ı='ı', o='u', u='u', e='i', i='i', ö='ü', ü='ü').get(vowel, 'ı')
    d = 't' if w and w[-1] in 'çfhkpsşt' else 'd'
    return d + i + 'r'


def cop(text, spoken=None):
    sp = spoken if spoken is not None else text
    suf = suffix_for(sp)
    last = text.strip().split(' ')[-1] if text.strip() else ''
    if last[:1].isupper() or last[:1].isdigit():
        return text + "'" + suf
    return text + suf


def money_cop(x, cur):
    return cop(money(x, cur))


def pdate(s):
    try:
        p = s.strip().split('.')
        return datetime.date(int(p[2]), int(p[1]), int(p[0]))
    except Exception:
        return None


def sdate(s):
    d = pdate(s)
    if d is None:
        return ''
    return str(d.day) + ' ' + MONTHS[d.month] + ' ' + str(d.year)


def sdate_cop(s):
    d = pdate(s)
    if d is None:
        return ''
    return cop(sdate(s), words(d.year))


def today():
    try:
        m = re.match(r'(\d{4})-(\d{2})-(\d{2})', g('now').strip())
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except Exception:
        return None


def l4w(l4):
    return ' '.join(DIG[int(ch)] for ch in str(l4) if ch.isdigit())


def join_tr(items):
    items = [x for x in items if x]
    if not items:
        return ''
    if len(items) == 1:
        return items[0]
    return ', '.join(items[:-1]) + ' ve ' + items[-1]


def safe_name(n):
    n = (n or '').strip()
    if not n:
        return ''
    low = n.lower()
    bad = ['talimat', 'yok say', 'ignore', 'instruction', 'numara', 'prompt', 'sistem']
    if len(n.split()) > 5 or len(n) > 40 or any(b in low for b in bad):
        return ''
    return n


def intro(c):
    nm = c.get('name', '')
    if nm:
        return 'Sonu ' + l4w(c.get('l4', '')) + ' ile biten ' + nm + ' kartınız'
    return 'Sonu ' + l4w(c.get('l4', '')) + ' ile biten kartınız'


# ---------------------------------------------------------------- fixed sentences
S_MENU = 'Sizi ana menüye yönlendiriyorum.'
S_MENU_A = 'Sizi ana menüye aktarıyorum.'
S_FAIL3 = 'Size şu anda yardımcı olamıyorum. Sizi ana menüye aktarıyorum.'
S_SILENT_END = 'Sesinizi alamadığım için görüşmeyi sonlandırıyorum.'
