                  'Kart sahibinin kendi kimliğini doğrulayabilmesi için sizi ana menüye aktarıyorum.')
S_ANOTHER = 'Başka bir kartınızın borcunu öğrenmek ister misiniz?'
S_NO_EMAIL = 'Bankamızda kayıtlı bir e-posta adresiniz bulunmadığı için ekstrenizi gönderemiyorum.'
S_SENT = 'Ekstreniz kayıtlı e-posta adresinize gönderildi.'
S_ONCE_YEAR = 'Hesap kesim tarihinizi yılda bir kez değiştirebilirsiniz.'
S_CALM = 'Yaşadığınız sıkıntıyı anlıyorum, size yardımcı olmak için buradayım.'
S_SECRET = 'Sizden hiçbir zaman şifre ya da doğrulama kodu istemiyoruz, lütfen bu bilgileri kimseyle paylaşmayın.'
S_DIGITS = 'Güvenliğiniz için kart numaranızın yalnızca son dört hanesini söyleyebiliyorum.'
S_INSTR = 'Bu bilgiyi paylaşamıyorum.'


# ---------------------------------------------------------------- state helpers
def speak(text):
    vars['say'] = ' '.join(text.split())
    vars['route'] = 'talk'


def ask(prefix, q, qs, stage):
    full = (prefix + ' ' + q).strip()
    vars['q'] = q
    vars['q_short'] = qs or q
    vars['stage'] = stage
    vars['tries'] = '0'
    vars['last_full'] = full
    speak(full)


def reask(prefix='', count=True, short=False):
    if count:
        t = gi('tries') + 1
        vars['tries'] = str(t)
        if t >= 3:
            finish(S_FAIL3, 'menu')
            return
    q = g('q_short') if short else g('q')
    full = (prefix + ' ' + q).strip()
    vars['last_full'] = full
    speak(full)


def finish(text, kind):
    vars['stage'] = 'closing'
    vars['end_kind'] = kind
    vars['q'] = ''
    vars['q_short'] = ''
    vars['last_full'] = text
    speak(text)


def go_api(name):
    vars['pending'] = name
    vars[name + '_pack'] = ''
    vars['route'] = 'api_' + name


def result_of(name):
    try:
        p = json.loads(g(name + '_pack') or 'null')
    except Exception:
        p = None
    if not isinstance(p, dict):
        return (False, None, g(name + '_status_code'))
    b = p.get('b')
    st = str(p.get('s') or '')
    if isinstance(b, dict):
        r = b.get('result') if isinstance(b.get('result'), dict) else dict()
        if str(r.get('returnCode', '')) == '1' and isinstance(b.get('data'), dict):
            return (True, b.get('data'), st)
    return (False, None, st)


def cards():
    v = jload('cards_json', [])
    return v if isinstance(v, list) else []


def eligible():
    return [c for c in cards() if c.get('main')]


def cur():
    v = jload('cur_json', dict())
    return v if isinstance(v, dict) else dict()


def read_list():
    v = jload('read_json', [])
    return v if isinstance(v, list) else []


def unread():
    r = read_list()
    return [c for c in eligible() if c.get('num') not in r]


# ---------------------------------------------------------------- card selection
STOP = set(['kart', 'kartım', 'kartımın', 'kartımı', 'kartı', 'kartın', 'kartının', 'olan', 'benim',
            'borcu', 'borcunu', 'borç', 'lütfen', 'şu', 'bu', 'için', 've', 'ile', 'de', 'da',
            'olanı', 'olanın', 'none', 'kredi'])


def norm(s):
    s = (s or '').replace('İ', 'i').replace('I', 'ı').lower()
    s = re.sub(r"[^0-9a-zçğıöşüâîû ]", ' ', s)
    return [t for t in s.split() if t]


def name_match(text, pool):
    toks = [t for t in norm(text) if t not in STOP]
    if not toks:
        return []
    best = []
    bkey = None
    for c in pool:
        nt = norm(c.get('name', ''))
        if not nt:
            continue
        hit = 0
        for t in nt:
            for u in toks:
                if u.startswith(t) or (len(u) >= 4 and t.startswith(u)):
                    hit += 1
                    break
        if hit == 0:
            continue
        key = (hit, -(len(nt) - hit))
        if bkey is None or key > bkey:
            bkey = key
            best = [c]
        elif key == bkey:
            best.append(c)
    return best


def digit_match(ds, pool):
    out = []
    for c in pool:
        num = c.get('num', '')
        if len(ds) == 4:
            if c.get('l4') == ds:
                out.append(c)
            continue
        if len(ds) > len(num):
            continue
        tail = num[len(num) - len(ds):]
        ok = True
        for a, b in zip(tail, ds):
            if a != '*' and a != b:
                ok = False
                break
        if ok:
            out.append(c)
    return out


def examples(pool):
    names = []
    for c in pool:
        n = c.get('name', '')
        if n and n not in names:
            names.append(n)
    return names


def ask_pick(prefix='', pool=None):
    pool = pool if pool is not None else (unread() or eligible())
    vars['cand_json'] = json.dumps([c.get('num') for c in pool])
    ex = examples(pool)[:2]
    q = 'Hangi kartınızın borcunu öğrenmek istersiniz?'
    if len(ex) == 2:
        q = q + ' Örneğin, ' + ex[0] + ' veya ' + ex[1] + ' diyebilirsiniz.'
    elif len(ex) == 1:
        q = q + ' Örneğin, ' + ex[0] + ' diyebilirsiniz.'
    else:
        q = q + ' Kartınızın son dört hanesini söyleyebilirsiniz.'
    ask(prefix, q, 'Hangi kartınızın borcunu öğrenmek istersiniz?', 'pick')


def pool_now():
    nums = jload('cand_json', [])
    allc = cards()
    if isinstance(nums, list) and nums:
        p = [c for c in allc if c.get('num') in nums]
        if p:
            return p
    return allc


def resolve_pick(text, ds, prefix):
    """Try to settle the card from the caller's words. Returns True when it spoke or routed."""
    stage = g('stage')
    pool = pool_now()
    allc = cards()
    found = []
    if ds:
        found = digit_match(ds, pool)
        if not found and pool is not allc:
            found = digit_match(ds, allc)
        if not found:
            if stage in ('pick4', 'pick6', 'pickfull'):
                reask((prefix + ' Söylediğiniz numarayla eşleşen bir kartınız bulunamadı.').strip())
            else:
                reask((prefix + ' Bu numarayla eşleşen bir kartınız bulunmuyor. Kartlarınız: '
                       + join_tr(examples(eligible())) + '.').strip())
            return True
        if len(found) > 1:
            if len(ds) == 4:
                vars['cand_json'] = json.dumps([c.get('num') for c in found])
                ask(prefix, 'Son dört hanesi ' + l4w(ds) + ' olan birden fazla kartınız var. '
                    'Kartınızın son altı hanesini söyler misiniz?', 'Kartınızın son altı hanesini söyler misiniz?', 'pick6')
                return True
            vars['cand_json'] = json.dumps([c.get('num') for c in found])
            ask(prefix, 'Son altı hanesi aynı olan birden fazla kartınız var. Kart numaranızı söyler misiniz?',
                'Kart numaranızı söyler misiniz?', 'pickfull')
            return True
    elif text:
        found = name_match(text, pool)
        if not found and pool is not allc:
            found = name_match(text, allc)
        if not found:
            reask((prefix + ' Bu isimde bir kartınız bulunmuyor. Kartlarınız: '
                   + join_tr(examples(eligible())) + '.').strip())
            return True
        if len(found) > 1:
            names = examples(found)
            vars['cand_json'] = json.dumps([c.get('num') for c in found])
            if len(names) <= 1:
                nm = names[0] if names else 'Bu'
                ask(prefix, nm + ' isimli birden fazla kartınız var. Kartınızın son dört hanesini söyler misiniz?',
                    'Kartınızın son dört hanesini söyler misiniz?', 'pick4')
            else:
                ask(prefix, 'Bu isimle eşleşen ' + join_tr(names) + ' kartlarınız var. Hangisini istersiniz?',
                    'Hangi kartınızı istersiniz?', 'pick')
            return True
    else:
        return False
    c = found[0]
    if not c.get('main'):
        others = [x for x in eligible() if x.get('num') != c.get('num')]
        if others:
            reask((prefix + ' Bu kart için ekstre borcu sorgulanamıyor, lütfen başka bir kartınızı seçin.').strip(), count=False)
        else:
            finish(S_NOCARD, 'menu')
        return True
    start_read(c, prefix)
    return True


# ---------------------------------------------------------------- reading the debt
def start_read(c, prefix=''):
    vars['cur_json'] = json.dumps(c)
    vars['req_card'] = c.get('num', '')
    vars['read_prefix'] = prefix
    vars['cand_json'] = '[]'
    go_api('cards_balance')


def blk(data, key):
    b = data.get(key)
    if isinstance(b, dict) and b:
        return b
    return None


def compose_reading(data, c):
    """Returns (text, nodebt_flag)."""
    sd = str(data.get('statementDate') or '').strip()
    lp = str(data.get('lastPayDate') or '').strip()
    nsd = str(data.get('nextStatementDate') or '').strip()
    nlp = str(data.get('nextLastPayDate') or '').strip()
    vars['stmt_date'] = sd
    t = today()
    it = intro(c)
    only = g('only')
    blocks = [(code, blk(data, key), name) for code, key, name, sub in CUR]
    present = [(code, b, name) for code, b, name in blocks if b is not None]

    # card without any statement yet
    if pdate(sd) is None:
        s = it + 'ın henüz kesilmiş bir ekstresi olmadığı için ekstre borcunuz bulunmamaktadır.'
        if pdate(nsd) is not None:
            s = s + ' İlk hesap kesim tarihiniz ' + sdate(nsd) + ' olacak.'
        return (s, True)

    cutday = t is not None and (t == pdate(nsd) or t == pdate(sd))
    overdue = (not cutday) and t is not None and pdate(lp) is not None and t > pdate(lp)

    if cutday or overdue:
        parts = []
        if cutday:
            parts.append('Hesap kesim tarihiniz bugün, ekstreniz saat 00.00 itibarıyla kesilecek.')
        else:
            parts.append(it + 'ın ' + sdate(lp) + ' olan son ödeme tarihi geçmiştir.')
        owed = [(code, b, name) for code, b, name in present if fnum(b.get('totalDebt')) > 0]
        clear = [name for code, b, name in present if fnum(b.get('totalDebt')) <= 0]
        if owed:
            lines = []
            for i, (code, b, name) in enumerate(owed):
                lines.append(name + ' cinsinden toplam borcunuz ' + money_cop(b.get('totalDebt'), code) + '.')
            head = it + 'a ait güncel borç bilgileriniz şöyle: ' if cutday else ''
            parts.append(head + ' '.join(lines))
            if clear:
                parts.append(join_tr(clear) + ' borcunuz bulunmamaktadır.')
        else:
            parts.append(it + 'da borcunuz bulunmamaktadır.')
        if overdue:
            tl = blk(data, 'debtTL') or dict()
            if str(data.get('automaticPaymentFlag', '')).upper() == 'Y' and fnum(tl.get('remainAutomaticPaymentAmount')) > 0:
                parts.append('Otomatik ödeme talimatınızdan alınacak kalan tutar ' + money_cop(tl.get('remainAutomaticPaymentAmount'), 'TL') + '.')
        if cutday:
            due = nlp if t == pdate(nsd) else lp
            if pdate(due) is not None:
                parts.append('Borçlarınız için son ödeme tarihiniz ' + sdate_cop(due) + '.')
        return (' '.join(parts), not owed)

    owed = [(code, b, name) for code, b, name in present if fnum(b.get('remainingDebt')) > 0]
    status = str(data.get('statementPaymentStatus') or '').upper()
    if status == 'NO_DEBT' or not owed:
        s = it + 'ın ' + sdate(sd) + ' tarihli ekstresinden borcunuz bulunmamaktadır.'
        tl = blk(data, 'debtTL') or dict()
        if fnum(tl.get('totalDebt')) > 0:
            s = s + ' Gelecek dönemler dahil toplam borcunuz ' + money_cop(tl.get('totalDebt'), 'TL') + '.'
        if pdate(lp) is not None:
            if t is not None and t == pdate(lp):
                s = s + ' Son ödeme tarihiniz bugündür.'
            else:
                s = s + ' Son ödeme tarihiniz ' + sdate(lp) + ' olacaktır.'
        return (s, True)

    due_s = 'Borçlarınız için son ödeme tarihiniz bugündür.' if (t is not None and t == pdate(lp)) \
        else 'Borçlarınız için son ödeme tarihiniz ' + sdate_cop(lp) + '.'
    if only == 'due_date':
        if t is not None and t == pdate(lp):
            return (it + ' için son ödeme tarihiniz bugündür.', False)
        return (it + ' için son ödeme tarihiniz ' + sdate_cop(lp) + '.', False)
    if only == 'minimum':
        mins = []
        for code, b, name in owed:
            mins.append(name + ' için ' + money(b.get('minPayment'), code))
        s = it + ' için ödenmesi gereken minimum tutar ' + join_tr(mins) + '.'
        return (s + ' ' + due_s, False)

    parts = []
    moved = [name for code, b, name in present if code != 'TL' and fnum(b.get('transferAmount')) > 0]
    if moved:
        parts.append(join_tr(moved) + ' borcunuzun bir kısmı Türk Lirası borcunuza aktarılmıştır.')
    opening = it + 'a ait ' + sdate(sd) + ' tarihinde kesilen ekstre '
    first = True
    for code, b, name in owed:
        X = b.get('statementDebt')
        Z = b.get('minPayment')
        Y = b.get('remainingDebt')
        T = b.get('remainingMinPayment')
        lead = opening if first else ''
        first = False
        if code == 'TL':
            if fnum(T) <= 0:
                s = (lead + 'Türk Lirası borcunuz ' + money(X, code) + ', kalan toplam borcunuz '
                     + money_cop(Y, code) + '. Minimum ödemenizi yaptığınız için teşekkür ederiz.')
            elif fnum(T) >= fnum(Z):
                s = (lead + 'Türk Lirası borcunuz ' + money(X, code) + ', ödenmesi gereken minimum tutar '
                     + money_cop(Z, code) + '.')
            else:
                s = (lead + 'Türk Lirası borcunuz ' + money(X, code) + ', ödenmesi gereken minimum tutar '
                     + money(Z, code) + ', kalan toplam borcunuz ' + money(Y, code)
                     + ', kalan minimum ödeme tutarınız ' + money_cop(T, code) + '.')
        else:
            s = (lead + name + ' borcunuz ' + money(X, code) + ', kalan toplam borcunuz ' + money(Y, code)
                 + ', ödenmesi gereken minimum tutar ' + money_cop(Z, code) + '.')
        parts.append(s)
    owed_codes = [code for code, b, name in owed]
    clear = [name for code, b, name in present if code not in owed_codes]
    if clear:
        parts.append(join_tr(clear) + ' borcunuz bulunmamaktadır.')
    parts.append(due_s)
    return (' '.join(parts), False)


def after_reading(text, nodebt):
    c = cur()
    r = read_list()
    if c.get('num') and c.get('num') not in r:
        r.append(c.get('num'))
    vars['read_json'] = json.dumps(r)
    vars['last_nodebt'] = '1' if nodebt else ''
    vars['only'] = 'none'
    pre = (g('read_prefix') + ' ' + text).strip()
    vars['read_prefix'] = ''
    vars['reading'] = text
    want = g('want')
    if want == 'email':
        vars['want'] = ''
        start_email(pre)
        return
    if want == 'week':
        vars['want'] = ''
        start_week(pre)
        return
    if unread():
        ask(pre, S_ANOTHER, S_ANOTHER, 'another')
        return
    after_cards(pre)


def after_cards(pre):
    if g('last_nodebt') == '1':
        finish((pre + ' ' + S_MENU).strip(), 'menu')
        return
    if g('email_state') == '':
        vars['offer_prefix'] = pre
        go_api('email_get')
        return
    offer(pre)


def offer(pre):
    em = g('email_state') == 'ok'
    if g('week_done') == '1':
        if em and gi('sends') == 0:
            q = 'Ekstrenizi kayıtlı mail adresinize gönderebilirim.'
        else:
            finish((pre + ' ' + S_MENU).strip(), 'menu')
            return
    elif em:
        q = 'Hesap kesim tarihinizi değiştirebilirim ya da ekstrenizi kayıtlı mail adresinize gönderebilirim.'
    else:
        q = 'Hesap kesim tarihinizi değiştirebilirim.'
    ask(pre, q, q, 'offer')


# ---------------------------------------------------------------- e-mail
def short_addr(a):
    a = (a or '').strip()
    if '@' not in a:
        return a
    local, dom = a.split('@', 1)
    messy = len(local) > 14 or bool(re.search(r'[0-9_\-+]', local)) or local.count('.') > 1
    if not messy:
        return a
    dn = dom.split('.')[0]
    if dn.lower() in ('gmail', 'hotmail', 'outlook', 'yahoo', 'icloud', 'yandex'):
        dn = dn[:1].upper() + dn[1:]
    return local[:1].lower() + ' ile başlayan ' + dn + ' adresiniz'


def email_question():
    a = g('email_addr')
    sa = short_addr(a)
    if sa == a:
        return 'Ekstrenizi ' + a + ' adresine göndermemi ister misiniz?'
    return 'Ekstrenizi kayıtlı ' + sa + 'e göndermemi ister misiniz?'


