    if st == 'none':
        if g('week_done') != '1':
            ask((pre + ' ' + S_NO_EMAIL).strip(), 'Hesap kesim tarihinizi değiştirebilirim.',
                'Hesap kesim tarihinizi değiştirebilirim.', 'offer')
        else:
            finish((pre + ' ' + S_NO_EMAIL + ' ' + S_MENU).strip(), 'menu')
        return
    if gi('sends') >= 3:
        finish((pre + ' ' + S_MENU).strip(), 'menu')
        return
    if pdate(g('stmt_date')) is None:
        c = cur()
        if not c.get('num'):
