        finish((pre + ' Kartınızın henüz kesilmiş bir ekstresi bulunmadığı için gönderebileceğim bir ekstre yok. ' + S_MENU).strip(), 'menu')
        return
    q = email_question()
    ask(pre, q, q, 'email_confirm')


