    if intent == 'not_my_address':
        finish((prefix + ' Bu durumda ekstrenizi gönderemiyorum. E-posta adresinizi bu görüşmede değiştiremiyorum. ' + S_MENU).strip(), 'menu')
        return
    finish((prefix + ' Ekstrenizi yalnızca son kesilen ekstre olarak ve bankamızda kayıtlı e-posta adresinize gönderebiliyorum; '
            'başka bir adrese, kağıt olarak ya da kısa mesajla gönderemiyorum. ' + S_MENU).strip(), 'menu')


def route_end():
    k = g('end_kind') or 'menu'
    if k not in ('menu', 'agent', 'ivr', 'hangup'):
        k = 'menu'
    vars['say'] = ''
    vars['route'] = 'end_' + k


